// Rebuilds codemirror.js and LICENSES.txt in this directory:  node docs/vendor/codemirror/build.mjs
// Installs the exact versions below from the npm registry into a temporary directory and bundles them with esbuild.
import { execFileSync } from "node:child_process";
import { existsSync, mkdtempSync, readFileSync, readdirSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const ESBUILD = "0.27.7";
// --- Packages imported by editor-cm.js
const ENTRY = {
  state: "@codemirror/state",
  view: "@codemirror/view",
  language: "@codemirror/language",
  commands: "@codemirror/commands",
  search: "@codemirror/search",
  markdown: "@codemirror/lang-markdown",
  highlight: "@lezer/highlight",
  autocomplete: "@codemirror/autocomplete",
};
// --- Every package that ends up in the bundle, pinned (direct and transitive)
const VERSIONS = {
  "@codemirror/autocomplete": "6.20.4",
  "@codemirror/commands": "6.11.1",
  "@codemirror/lang-css": "6.3.1",
  "@codemirror/lang-html": "6.4.12",
  "@codemirror/lang-javascript": "6.2.5",
  "@codemirror/lang-markdown": "6.5.2",
  "@codemirror/language": "6.13.1",
  "@codemirror/lint": "6.9.8",
  "@codemirror/search": "6.7.2",
  "@codemirror/state": "6.7.6",
  "@codemirror/streamparser": "6.0.0",
  "@codemirror/view": "6.43.15",
  "@lezer/common": "1.5.3",
  "@lezer/css": "1.3.9",
  "@lezer/highlight": "1.2.5",
  "@lezer/html": "1.3.13",
  "@lezer/javascript": "1.5.6",
  "@lezer/lr": "1.4.12",
  "@lezer/markdown": "1.8.1",
  "@marijn/find-cluster-break": "1.0.4",
  crelt: "1.0.7",
  "style-mod": "4.1.4",
  "w3c-keyname": "2.2.8",
};

const here = dirname(fileURLToPath(import.meta.url));
const work = mkdtempSync(join(tmpdir(), "mdsig-codemirror-"));
try {
  writeFileSync(join(work, "package.json"), JSON.stringify({ private: true, dependencies: VERSIONS, overrides: VERSIONS, devDependencies: { esbuild: ESBUILD } }));
  execFileSync("npm", ["install", "--no-audit", "--no-fund", "--ignore-scripts"], { cwd: work, stdio: "inherit" });

  const modules = join(work, "node_modules");
  const installed = [];
  for (const scope of readdirSync(modules)) {
    if (scope.startsWith(".")) continue;
    const names = scope.startsWith("@") ? readdirSync(join(modules, scope)).map((n) => `${scope}/${n}`) : [scope];
    for (const name of names) if (!/^(@esbuild\/|esbuild$)/.test(name)) installed.push(name);
  }
  installed.sort();
  for (const name of installed) {
    const got = JSON.parse(readFileSync(join(modules, name, "package.json"), "utf8")).version;
    if (VERSIONS[name] !== got) throw new Error(`${name}: installed ${got}, pinned ${VERSIONS[name] ?? "nothing"}`);
  }

  writeFileSync(join(work, "entry.js"), Object.entries(ENTRY).map(([k, pkg]) => `export * as ${k} from ${JSON.stringify(pkg)};`).join("\n") + "\n");
  const list = installed.map((n) => `${n}@${VERSIONS[n]}`).join(" ");
  const banner = `/* CodeMirror 6 bundle for md-signature. Generated by build.mjs with esbuild ${ESBUILD}; do not edit. MIT licences in LICENSES.txt. Packages: ${list} */`;
  execFileSync(join(modules, ".bin", "esbuild"), ["entry.js", "--bundle", "--format=esm", "--target=es2022", "--minify", "--legal-comments=none", `--banner:js=${banner}`, `--outfile=${join(here, "codemirror.js")}`], { cwd: work, stdio: "inherit" });

  let licences = "Licences of the packages bundled in codemirror.js\n";
  for (const name of installed) {
    const dir = join(modules, name);
    const file = ["LICENSE", "LICENSE.md", "LICENSE.txt", "license"].map((f) => join(dir, f)).find(existsSync);
    if (!file) throw new Error(`${name}: no licence file`);
    licences += `\n${"=".repeat(78)}\n${name}@${VERSIONS[name]}\n${"=".repeat(78)}\n\n${readFileSync(file, "utf8").trim()}\n`;
  }
  writeFileSync(join(here, "LICENSES.txt"), licences);
} finally {
  rmSync(work, { recursive: true, force: true });
}
